import React, { useEffect, useMemo, useState } from 'react';
import motifsData from '../data/motifs.json';
import { Motif } from '../types/motif';
import { averageEmbeddings, cosineSimilarity, findNearest, resolvePublicImagePath, RawMotif } from '../utils/practiceSearch';
import { calculateScore } from '../utils/practiceScoring';
import { getTarotCompact } from '../utils/tarotMapping';
import { getIChingCompact } from '../utils/ichingMapping';
import '../App.css';

type Hand = {
  cards: RawMotif[]; // 5 cards
  target: RawMotif;  // 1 target
};

function sampleDistinct<T>(arr: T[], k: number): T[] {
  const n = arr.length;
  const res: T[] = [];
  const used = new Set<number>();
  while (res.length < Math.min(k, n)) {
    const idx = Math.floor(Math.random() * n);
    if (used.has(idx)) continue;
    used.add(idx);
    res.push(arr[idx]);
  }
  return res;
}

function useMotifs(): RawMotif[] {
  // Use full bundled motifs dataset (all 1265 motifs)
  return useMemo(() => {
    const all = (motifsData as unknown as Motif[]) || [];
    // Keep only fields needed for practice mode
    const mapped: RawMotif[] = all.map(m => ({
      id: m.id,
      name: m.name,
      embedding: m.embedding || [],
      image_path: m.image_path,
      tarot_index: m.tarot_index,
      iching_hexagram_number: m.iching_hexagram_number,
      chapter: m.chapter,
    }));
    return mapped;
  }, []);
}

export default function Practice(): React.ReactElement {
  const motifs = useMotifs();
  const [hand, setHand] = useState<Hand | null>(null);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [scoreTotal, setScoreTotal] = useState<number>(0);
  const [roundsPlayed, setRoundsPlayed] = useState<number>(0);
  const [playing, setPlaying] = useState<boolean>(false);
  const [helpOpen, setHelpOpen] = useState<boolean>(false);

  useEffect(() => {
    if (motifs.length > 10) {
      newRound();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [motifs.length]);

  function newRound(): void {
    const six = sampleDistinct(motifs, 6);
    const cards = six.slice(0, 5);
    const target = six[5];
    setHand({ cards, target });
    setSelectedIds(new Set());
  }

  function toggleCard(id: string): void {
    setSelectedIds(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  const fusion = useMemo(() => {
    if (!hand) return null;
    const selected = hand.cards.filter(c => selectedIds.has(c.id));
    if (selected.length === 0) return null;
    // If only one card is selected, use it directly (no fusion)
    if (selected.length === 1) {
      const only = selected[0];
      const simToTarget = cosineSimilarity(only.embedding || [], hand.target.embedding || []);
      const scoring = calculateScore(only as unknown as Motif, hand.target as unknown as Motif, simToTarget);
      return { result: only, similarity: simToTarget, scoring };
    }
    // For multiple, fuse then find nearest (excluding inputs)
    const avg = averageEmbeddings(selected.map(c => c.embedding || []));
    if (!avg) return null;
    const pool = motifs;
    const exclude = new Set<string>(selected.map(c => c.id));
    const { motif } = findNearest(avg, pool, exclude);
    if (!motif) return null;
    const simToTarget = cosineSimilarity(motif.embedding || [], hand.target.embedding || []);
    const scoring = calculateScore(motif as Motif, hand.target as Motif, simToTarget);
    return { result: motif, similarity: simToTarget, scoring };
  }, [hand, selectedIds, motifs]);

  function onNextHand(): void {
    setRoundsPlayed(r => r + 1);
    if (fusion?.scoring.totalPoints) setScoreTotal(s => s + fusion.scoring.totalPoints);
    newRound();
  }

  function onShuffle(): void {
    if (!hand) return;
    const cards = sampleDistinct(motifs.filter(m => m.id !== hand.target.id), 5);
    setHand({ cards, target: hand.target });
    setSelectedIds(new Set());
  }

  function onReset(): void {
    setScoreTotal(0);
    setRoundsPlayed(0);
    newRound();
  }

  function onSubmitScore(): void {
    try {
      const entry = {
        at: new Date().toISOString(),
        total: scoreTotal,
        rounds: roundsPlayed,
      };
      const key = 'practice-highscores';
      const existing = JSON.parse(localStorage.getItem(key) || '[]');
      existing.push(entry);
      localStorage.setItem(key, JSON.stringify(existing));
      // Stub: wire this to Sheets later (silent save)
    } catch {
      // ignore
    }
  }

  function imageSrc(m: RawMotif): string | undefined {
    return resolvePublicImagePath(m.image_path) || undefined;
  }

  const activeBonusTypes = new Set((fusion?.scoring.bonuses || []).map(b => b.type));
  const uniqueIChing = useMemo(() => {
    const s = new Set<number>();
    for (const m of motifs) if (typeof m.iching_hexagram_number === 'number') s.add(m.iching_hexagram_number);
    return s;
  }, [motifs]);

  return (
    <div className="practice-container" style={{ padding: 12, maxWidth: 480, margin: '0 auto', background: 'var(--bg)', color: 'var(--text)', minHeight: '100vh' }}>
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8, textAlign: 'center' }}>
        <h2 style={{ margin: '8px 0' }}>
          Glass Bead Game
          <br />
          <span style={{ fontWeight: 500 }}>Practice mode</span>
        </h2>
        <button aria-label="Help" onClick={() => setHelpOpen(true)} style={{ height: 28, padding: '0 10px', borderRadius: 14, border: '1px solid var(--border)', background: 'var(--panel)', color: 'var(--text)', display: 'flex', alignItems: 'center', gap: 6, fontSize: 12 }}>
          <span>?</span>
          <span className="mono" style={{ fontSize: 11, opacity: 0.8 }}>{motifs.length}</span>
        </button>
      </div>

      {/* Scoreboard under title */}
      <div style={{ display: 'flex', gap: 8, marginTop: 10, marginBottom: 8 }}>
        <div className="mono" style={{ padding: '6px 10px', background: 'rgba(86,156,214,0.16)', color: 'var(--accent-blue)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Total: {scoreTotal.toLocaleString()}</div>
        <div className="mono" style={{ padding: '6px 10px', background: 'rgba(79,193,255,0.16)', color: 'var(--accent-cyan)', borderRadius: 9999, fontWeight: 700, fontSize: 12 }}>Hands: {roundsPlayed}</div>
      </div>

      {/* Target */}
      <div style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 10, marginBottom: 12, background: 'var(--panel)' }}>
        <div style={{ fontWeight: 600, marginBottom: 8 }}>Target</div>
        <div style={{ display: 'flex', gap: 8 }}>
          {hand && imageSrc(hand.target) ? (
            <img src={imageSrc(hand.target)!} alt={hand.target.name} style={{ width: 120, borderRadius: 4, border: '1px solid #3a3a3a' }} />
          ) : (
            <div style={{ width: 120, height: 120, background: '#f2f2f2', borderRadius: 4 }} />
          )}
          <div style={{ fontSize: 13 }}>
            <div className="mono" style={{ fontWeight: 700 }}>{hand?.target.id}</div>
            <div>{hand?.target.name}</div>
            <div style={{ marginTop: 4, color: 'var(--muted)', fontSize: 12 }}>
              <span style={{ color: activeBonusTypes.has('tarot') ? '#1967d2' : undefined }}>
                {hand?.target.tarot_index !== undefined ? getTarotCompact(hand.target.tarot_index) : ''}
              </span>
              {hand?.target.iching_hexagram_number !== undefined ? '  ' : ''}
              <span style={{ color: activeBonusTypes.has('iching') ? '#d23b3b' : undefined }}>
                {hand?.target.iching_hexagram_number !== undefined ? getIChingCompact(hand.target.iching_hexagram_number) : ''}
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* Fusion Result */}
      <div style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 10, marginBottom: 12, transition: 'transform 200ms ease', transform: playing ? 'scale(1.03)' : 'scale(1)', background: 'var(--panel)' }}>
        <div style={{ fontWeight: 600, marginBottom: 8 }}>Fusion Result</div>
        <div style={{ display: 'flex', gap: 8 }}>
          {fusion && imageSrc(fusion.result) ? (
            <img src={imageSrc(fusion.result)!} alt={fusion.result.name} style={{ width: 120, borderRadius: 4, border: '1px solid #3a3a3a' }} />
          ) : (
            <div style={{ width: 120, height: 120, background: '#2a2a2a', borderRadius: 4, border: '1px solid #3a3a3a' }} />
          )}
          <div style={{ fontSize: 13 }}>
            <div className="mono" style={{ fontWeight: 700 }}>{fusion ? fusion.result.id : '—'}</div>
            <div>{fusion ? fusion.result.name : '—'}</div>
            <div style={{ marginTop: 4, color: 'var(--muted)', fontSize: 12 }}>
              <span style={{ color: activeBonusTypes.has('tarot') ? '#1967d2' : undefined }}>
                {fusion && (fusion.result as any).tarot_index !== undefined ? getTarotCompact((fusion.result as any).tarot_index as number) : ''}
              </span>
              {fusion && (fusion.result as any).iching_hexagram_number !== undefined ? '  ' : ''}
              <span style={{ color: activeBonusTypes.has('iching') ? '#d23b3b' : undefined }}>
                {fusion && (fusion.result as any).iching_hexagram_number !== undefined ? getIChingCompact((fusion.result as any).iching_hexagram_number as number) : ''}
              </span>
            </div>
            <div className="mono" style={{ marginTop: 6, color: 'var(--muted)' }}>Similarity: {fusion ? fusion.similarity.toFixed(3) : '—'}</div>
            <div style={{ marginTop: 6 }}>
              <span className="mono" style={{ display: 'inline-block', padding: '6px 10px', borderRadius: 8, background: '#0e639c22', border: '1px solid #0e639c40', color: '#d4e7ff', fontWeight: 800, fontSize: 18 }}>
                Score: {fusion ? fusion.scoring.totalPoints.toLocaleString() : '0'}
              </span>
            </div>
          </div>
        </div>
        <div style={{ marginTop: 8, fontSize: 12 }}>
          <div style={{ fontWeight: 600 }}>Breakdown</div>
          <div>Base: {fusion ? fusion.scoring.basePoints.toLocaleString() : '0'}</div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, marginTop: 6 }}>
            {fusion && fusion.scoring.bonuses.length > 0 ? (
              fusion.scoring.bonuses.map((b, i) => (
                <BonusBadge key={i} type={b.type} text={`×${b.multiplier} – ${b.label}`} />
              ))
            ) : (
              <div style={{ color: '#777' }}>No bonuses</div>
            )}
          </div>
        </div>
      </div>

      {/* Your Hand */}
      <div style={{ border: '1px solid var(--border)', borderRadius: 8, padding: 10, marginBottom: 72, background: 'var(--panel)' }}>
        <div style={{ fontWeight: 600, marginBottom: 8 }}>Your Hand</div>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, minmax(0, 1fr))', gap: 8 }}>
            {hand?.cards.map(card => {
              const isSelected = selectedIds.has(card.id);
              const selectedCount = selectedIds.size;
              const selectedSingle = isSelected && selectedCount === 1;
              const selectedMulti = isSelected && selectedCount > 1;
              return (
              <button
                key={card.id}
                onClick={() => toggleCard(card.id)}
                title={card.name}
                style={{
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: 6,
                border: selectedSingle ? '2px solid #ffffffcc' : (selectedMulti ? '2px solid #89d185' : '1px solid var(--border)'),
                  borderRadius: 8,
                background: isSelected ? '#2a2a2a' : '#252525',
                  minHeight: 120,
                  position: 'relative'
                }}
              >
                {imageSrc(card) ? (
                <img src={imageSrc(card)!} alt={card.name} style={{ width: '100%', borderRadius: 4, border: '1px solid #3a3a3a' }} />
                ) : (
                  <div style={{ width: '100%', height: 80, background: '#f2f2f2', borderRadius: 4 }} />
                )}
               <div className="mono" style={{ fontSize: 12, textAlign: 'center', marginTop: 4 }}>{card.id}</div>
               <div style={{ fontSize: 12, textAlign: 'center', marginTop: 2, color: 'var(--muted)' }}>
                  {(card.tarot_index !== undefined ? getTarotCompact(card.tarot_index) : '')}
                  {card.iching_hexagram_number !== undefined ? `  ${getIChingCompact(card.iching_hexagram_number)}` : ''}
                </div>
                {selectedMulti && (
                  <div className="mono" style={{ position: 'absolute', top: 6, right: 6, background: '#15331f', color: '#89d185', borderRadius: 6, padding: '2px 6px', fontSize: 10 }}>fuse</div>
                )}
              </button>
            );})}
          </div>
        </div>
      {/* Scoreboard */}
      <div style={{ display: 'none' }} />

      {/* Sticky Play bar */}
      <div style={{ position: 'fixed', left: 0, right: 0, bottom: 0, padding: 12, paddingBottom: 'calc(12px + env(safe-area-inset-bottom))', backdropFilter: 'blur(6px)', background: 'var(--sticky)', borderTop: '1px solid var(--border)' }}>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <button
            onClick={() => {
              if (!fusion) return;
              setPlaying(true);
              setTimeout(() => {
                setPlaying(false);
                setRoundsPlayed(r => r + 1);
                setScoreTotal(s => s + (fusion?.scoring.totalPoints || 0));
                newRound();
              }, 200);
            }}
            style={{ flex: 1, height: 52, borderRadius: 8, background: 'var(--play)', color: '#fff', border: 'none', fontSize: 16, fontWeight: 700 }}
          >
            Play
          </button>
          <OverflowMenu onReset={onReset} onSubmit={onSubmitScore} />
        </div>
      </div>

      {/* Help Modal */}
      {helpOpen && (
        <div role="dialog" aria-modal="true" style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.35)', display: 'flex', alignItems: 'flex-end' }} onClick={() => setHelpOpen(false)}>
          <div style={{ background: 'var(--panel)', color: 'var(--text)', border: '1px solid var(--border)', width: '100%', maxWidth: 520, margin: '0 auto', borderTopLeftRadius: 12, borderTopRightRadius: 12, padding: 16, maxHeight: '75vh', overflow: 'auto' }} onClick={e => e.stopPropagation()}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h3 style={{ margin: 0 }}>How to Play</h3>
              <button onClick={() => setHelpOpen(false)} style={{ border: '1px solid var(--border)', color: 'var(--text)', borderRadius: 6, background: 'var(--panel)', height: 28, padding: '0 10px' }}>Close</button>
            </div>
            <div style={{ fontSize: 13, color: 'var(--text)', marginTop: 8 }}>
              <p>Tap cards to select. If one card is selected, it is used directly. If multiple cards are selected, they are fused by averaging their embeddings and the nearest motif is chosen (excluding selected inputs).</p>
              <p>Scoring combines similarity with bonuses for Tarot, I Ching trigram, shared title words and chapter. Bonus pills below the score indicate exactly what applied.</p>
              <p style={{ marginTop: 12 }}>
                Dataset: using {uniqueIChing.size}/64 I Ching hexagrams covered; practice pool size: {motifs.length} motifs.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const btnStyle: React.CSSProperties = {
  padding: '10px 12px',
  borderRadius: 8,
  background: 'var(--play)',
  color: '#fff',
  border: 'none'
};

const btnStyleAlt: React.CSSProperties = {
  ...btnStyle,
  background: '#555'
};

function BonusBadge(props: { type: 'tarot' | 'iching' | 'title' | 'chapter'; text: string }) {
  const color = props.type === 'tarot' ? { bg: 'var(--pill-tarot-bg)', fg: 'var(--pill-tarot-fg)' }
    : props.type === 'iching' ? { bg: 'var(--pill-iching-bg)', fg: 'var(--pill-iching-fg)' }
    : props.type === 'title' ? { bg: 'var(--pill-title-bg)', fg: 'var(--pill-title-fg)' }
    : { bg: 'var(--pill-chapter-bg)', fg: 'var(--pill-chapter-fg)' };
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '4px 8px', borderRadius: 10, background: color.bg, color: color.fg, border: `1px solid ${color.fg}22`, fontSize: 11 }}>
      <span style={{ width: 6, height: 6, borderRadius: 6, background: color.fg, display: 'inline-block' }} />
      {props.text}
    </span>
  );
}

function OverflowMenu(props: { onReset: () => void; onSubmit: () => void }) {
  const [open, setOpen] = React.useState(false);
  return (
    <div style={{ position: 'relative' }}>
      <button aria-label="More" onClick={() => setOpen(o => !o)} style={{ width: 52, height: 52, borderRadius: 8, border: '1px solid var(--border)', background: 'var(--panel)', color: 'var(--text)' }}>⋯</button>
      {open && (
        <div style={{ position: 'absolute', bottom: 56, right: 0, background: 'var(--panel)', color: 'var(--text)', border: '1px solid var(--border)', borderRadius: 8, padding: 8, minWidth: 160, boxShadow: '0 4px 12px rgba(0,0,0,0.3)' }}>
          <button onClick={() => { props.onReset(); setOpen(false); }} style={{ display: 'block', width: '100%', textAlign: 'left', padding: 8, background: 'transparent', border: 'none', color: 'var(--text)' }}>Reset</button>
          <button onClick={() => { props.onSubmit(); setOpen(false); }} style={{ display: 'block', width: '100%', textAlign: 'left', padding: 8, background: 'transparent', border: 'none', color: 'var(--text)' }}>Submit score (stub)</button>
        </div>
      )}
    </div>
  );
}


