import { Motif } from '../types/motif';
import { getTarotCompact } from './tarotMapping';
import { getIChingCompact } from './ichingMapping';

/**
 * MotifBead - A simple game object representing a motif "bead" on the Miro board
 * This is a grouped image + text that moves together as one unit
 */
export class MotifBead {
  private motif: Motif;
  private groupId: string;
  private imageId: string;
  private textId: string;
  
  // Short-lived position cache to avoid repeated API calls in tight loops
  private cachedPosition: { x: number; y: number } | null = null;
  private cachedAtMs: number = 0;

  constructor(
    motif: Motif,
    groupId: string,
    imageId: string,
    textId: string
  ) {
    this.motif = motif;
    this.groupId = groupId;
    this.imageId = imageId;
    this.textId = textId;
  }

  /**
   * Get the motif data
   */
  getMotif(): Motif {
    return this.motif;
  }

  /**
   * Get the group ID
   */
  getGroupId(): string {
    return this.groupId;
  }

  /**
   * Get the image ID
   */
  getImageId(): string {
    return this.imageId;
  }

  /**
   * Get the embedding vector for this motif
   */
  getEmbedding(): number[] {
    return this.motif.embedding || [];
  }

  /**
   * Get the motif ID (primary key)
   */
  getMotifId(): string {
    return this.motif.id;
  }

  /**
   * Get the text ID
   */
  getTextId(): string {
    return this.textId;
  }

  /**
   * Get current position by fetching the group from Miro
   */
  async getPosition(): Promise<{ x: number; y: number }> {
    try {
      // Serve from cache if fresh (<= 1000ms)
      const now = Date.now();
      if (this.cachedPosition && now - this.cachedAtMs <= 1000) {
        return this.cachedPosition;
      }

      // Prefer group center if available
      const groupResult = await window.miro.board.get({ id: this.groupId, type: 'group' });
      const group = Array.isArray(groupResult) ? groupResult[0] : groupResult;
      if (group && typeof group.x === 'number' && typeof group.y === 'number') {
        this.cachedPosition = { x: group.x, y: group.y };
        this.cachedAtMs = now;
        return this.cachedPosition;
      }

      // Fallback to image center (reliable for connectors and positioning)
      const imgResult = await window.miro.board.get({ id: this.imageId, type: 'image' });
      const image = Array.isArray(imgResult) ? imgResult[0] : imgResult;
      if (image && typeof image.x === 'number' && typeof image.y === 'number') {
        this.cachedPosition = { x: image.x, y: image.y };
        this.cachedAtMs = now;
        return this.cachedPosition;
      }

      // Final fallback to text item
      const txtResult = await window.miro.board.get({ id: this.textId, type: 'text' });
      const text = Array.isArray(txtResult) ? txtResult[0] : txtResult;
      if (text && typeof text.x === 'number' && typeof text.y === 'number') {
        this.cachedPosition = { x: text.x, y: text.y };
        this.cachedAtMs = now;
        return this.cachedPosition;
      }

      // As a last resort, return a safe default instead of throwing to avoid cascading failures
      console.warn('No center position available for bead; returning (0,0)');
      this.cachedPosition = { x: 0, y: 0 };
      this.cachedAtMs = now;
      return this.cachedPosition;
    } catch (error) {
      console.error('Error getting bead position:', error);
      // Return safe default to keep upstream logic resilient
      return { x: 0, y: 0 };
    }
  }

  /**
   * Invalidate the cached position (call after moves/syncs)
   */
  invalidatePositionCache(): void {
    this.cachedAtMs = 0;
    this.cachedPosition = null;
  }

  /**
   * Move the entire bead to a new position
   * This moves the group, which moves all items together
   */
  async move(newX: number, newY: number): Promise<void> {
    try {
      const group = await window.miro.board.get({ id: this.groupId });
      await group.sync({
        x: newX,
        y: newY
      });
      console.log(`Moved motif bead ${this.motif.id} to (${newX}, ${newY})`);
      this.cachedPosition = { x: newX, y: newY };
      this.cachedAtMs = Date.now();
    } catch (error) {
      console.error('Error moving motif bead:', error);
      throw error;
    }
  }

  /**
   * Generate text content for motif display with tarot and I Ching symbols
   */
  private generateMotifText(motif: Motif): string {
    let content = `${motif.id}\n${motif.name}`;
    
    // Add tarot information if available
    if (motif.tarot_index !== undefined) {
      const tarotSymbol = getTarotCompact(motif.tarot_index);
      content += `\n\n${tarotSymbol}`;
    }
    
    // Add I Ching information if available
    if (motif.iching_hexagram_number !== undefined) {
      const ichingSymbol = getIChingCompact(motif.iching_hexagram_number);
      content += `\n${ichingSymbol}`;
    }
    
    return content;
  }

  /**
   * Update the motif data and refresh the display
   */
  async update(newMotif: Motif): Promise<void> {
    try {
      this.motif = newMotif;

      // Update the image
      if (newMotif.image_path) {
        const imageDataUrl = await this.loadImageAsDataURL(newMotif.image_path);
        const imageItem = await window.miro.board.get({ id: this.imageId });
        await imageItem.sync({
          url: imageDataUrl
        });
      }

      // Update the text
      const textItem = await window.miro.board.get({ id: this.textId });
      const textContent = this.generateMotifText(newMotif);
      await textItem.sync({
        content: textContent
      });

      // Update metadata
      await this.storeMetadata();

      console.log(`Updated motif bead ${newMotif.id}`);
    } catch (error) {
      console.error('Error updating motif bead:', error);
      throw error;
    }
  }

  /**
   * Delete the entire bead from the board
   */
  async delete(): Promise<void> {
    try {
      await window.miro.board.remove([this.groupId]);
      console.log(`Deleted motif bead ${this.motif.id}`);
    } catch (error) {
      console.error('Error deleting motif bead:', error);
      throw error;
    }
  }

  /**
   * Get the distance to another bead
   */
  async distanceTo(other: MotifBead): Promise<number> {
    const thisPos = await this.getPosition();
    const otherPos = await other.getPosition();
    const dx = thisPos.x - otherPos.x;
    const dy = thisPos.y - otherPos.y;
    return Math.sqrt(dx * dx + dy * dy);
  }

  /**
   * Check if this bead contains a point
   */
  async containsPoint(x: number, y: number): Promise<boolean> {
    const pos = await this.getPosition();
    const group = await window.miro.board.get({ id: this.groupId });
    const halfWidth = group.width / 2;
    const halfHeight = group.height / 2;
    
    return (
      x >= pos.x - halfWidth &&
      x <= pos.x + halfWidth &&
      y >= pos.y - halfHeight &&
      y <= pos.y + halfHeight
    );
  }

  /**
   * Load image as data URL
   */
  private async loadImageAsDataURL(imagePath: string): Promise<string> {
    try {
      const response = await fetch(`/${imagePath}`);
      if (!response.ok) {
        throw new Error(`Failed to load image: ${imagePath}`);
      }
      const blob = await response.blob();
      return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.readAsDataURL(blob);
      });
    } catch (error) {
      console.error('Error loading image:', error);
      // Return placeholder
      return 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==';
    }
  }

  /**
   * Store metadata on the image item
   */
  private async storeMetadata(): Promise<void> {
    try {
      const imageItem = await window.miro.board.get({ id: this.imageId });
      await imageItem.setMetadata('motifBead', {
        motifId: this.motif.id,
        groupId: this.groupId,
        imageId: this.imageId,
        textId: this.textId,
        name: this.motif.name,
        chapter: this.motif.chapter,
        description: this.motif.description,
        level: this.motif.level,
        // Note: embedding stored separately in motifs.json for performance
      });
    } catch (error) {
      console.error('Error storing metadata:', error);
    }
  }

  /**
   * Get the image data as a data URL for download/export
   */
  async getImageDataUrl(): Promise<string> {
    try {
      // Get the image directly using the stored image ID
      const [image] = await window.miro.board.get({ 
        type: 'image', 
        id: this.imageId 
      });
      
      if (!image) {
        throw new Error(`Image ${this.imageId} not found on board`);
      }
      
      // Try different methods to get image data
      if (image.url) {
        // Original image still has URL
        console.log(`📥 Retrieved image URL for ${this.motif.id}`);
        return image.url;
      }
      
      // For replaced images, try to get the actual image data
      if (typeof image.getFile === 'function') {
        try {
          const file = await image.getFile();
          const dataUrl = await this.fileToDataUrl(file);
          console.log(`📥 Retrieved image file data for ${this.motif.id}`);
          return dataUrl;
        } catch (fileError) {
          console.warn(`getFile() failed for ${this.motif.id}:`, fileError);
        }
      }
      
      if (typeof image.getDataUrl === 'function') {
        try {
          const dataUrl = await image.getDataUrl();
          console.log(`📥 Retrieved image dataUrl for ${this.motif.id}`);
          return dataUrl;
        } catch (dataUrlError) {
          console.warn(`getDataUrl() failed for ${this.motif.id}:`, dataUrlError);
        }
      }
      
      // If all else fails, try to extract from the image element
      if (image.imageUrl) {
        console.log(`📥 Retrieved imageUrl for ${this.motif.id}`);
        return image.imageUrl;
      }
      
      throw new Error('No method available to get image data');
    } catch (error) {
      console.error(`Error getting image data for ${this.motif.id}:`, error);
      throw error;
    }
  }

  /**
   * Convert File object to data URL
   */
  private fileToDataUrl(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result as string);
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  /**
   * Get the base filename for this bead's image (matches original)
   */
  getImageFilename(): string {
    if (this.motif.image_path) {
      const filename = this.motif.image_path.split('/').pop();
      if (filename) {
        return filename;
      }
    }
    return `${this.motif.id}.png`;
  }

  /**
   * Create a copy of this bead at a new position
   */
  async clone(newX: number, newY: number): Promise<MotifBead> {
    try {
      // Create new image
      if (!this.motif.image_path) {
        throw new Error(`No image path provided for motif ${this.motif.id}`);
      }
      const imageDataUrl = await this.loadImageAsDataURL(this.motif.image_path);
      const newImage = await window.miro.board.createImage({
        url: imageDataUrl,
        x: newX,
        y: newY,
        width: 180,
      });

      // Create multiple text fields for better layout
      // ID text (smaller, less prominent)
      const newIdText = await window.miro.board.createText({
        content: this.motif.id,
        x: newX,
        y: newY + 100,
        width: 500,  // Much wider for comfortable reading
        style: {
          textAlign: 'center',
          fontSize: 10,  // Slightly smaller for multi-line
          fontFamily: 'Arial',
          color: '#666666',
          fillColor: 'transparent'
        }
      });

      // Name text (LARGEST, most prominent)
      const newNameText = await window.miro.board.createText({
        content: this.motif.name,
        x: newX,
        y: newY + 125,  // More space for ID wrapping
        width: 500,  // Much wider for comfortable reading
        style: {
          textAlign: 'center',
          fontSize: 13,  // Slightly smaller for multi-line
          fontFamily: 'Arial',
          color: '#000000',
          fillColor: 'transparent'
        }
      });

      // Combined Tarot + I-Ching text on same line (if available)
      let newSymbolText = null;
      const symbols = [];
      if (this.motif.tarot_index !== undefined) {
        symbols.push(getTarotCompact(this.motif.tarot_index));
      }
      if (this.motif.iching_hexagram_number !== undefined) {
        symbols.push(getIChingCompact(this.motif.iching_hexagram_number));
      }

      if (symbols.length > 0) {
        newSymbolText = await window.miro.board.createText({
          content: symbols.join('  '),  // Two spaces between symbols
          x: newX,
          y: newY + 170,  // More space for name wrapping
          width: 500,  // Much wider
          style: {
            textAlign: 'center',
            fontSize: 11,  // Slightly smaller
            fontFamily: 'Arial',
            color: '#555555',
            fillColor: 'transparent'
          }
        });
      }

      // Group them
      const itemsToGroup = [newImage, newIdText, newNameText];
      if (newSymbolText) itemsToGroup.push(newSymbolText);

      const newGroup = await window.miro.board.group({
        items: itemsToGroup
      });

      // Create new bead
      const clonedBead = new MotifBead(
        this.motif,
        newGroup.id,
        newImage.id,
        newIdText.id
      );

      // Store metadata
      await clonedBead.storeMetadata();

      console.log(`Cloned motif bead ${this.motif.id}`);
      return clonedBead;
    } catch (error) {
      console.error('Error cloning motif bead:', error);
      throw error;
    }
  }
}
