import { Motif } from '../types/motif';
import motifsData from '../data/motifs.json';

function cosineSimilarity(a: number[], b: number[]): number {
  if (!a || !b || a.length !== b.length || a.length === 0) return -Infinity;
  let dot = 0;
  let ma = 0;
  let mb = 0;
  for (let i = 0; i < a.length; i++) {
    const av = a[i];
    const bv = b[i];
    dot += av * bv;
    ma += av * av;
    mb += bv * bv;
  }
  const denom = Math.sqrt(ma) * Math.sqrt(mb);
  if (denom === 0) return -Infinity;
  return dot / denom;
}

export class EmbeddingIndex {
  private motifs: Motif[];

  constructor() {
    // Filter to motifs that at least have an embedding array
    this.motifs = (Array.isArray(motifsData) ? motifsData : []).filter(
      (m) => Array.isArray(m.embedding) && m.embedding!.length > 0
    );
  }

  size(): number {
    return this.motifs.length;
  }

  getMotif(id: string): Motif | undefined {
    return this.motifs.find((m) => m.id === id);
  }

  nearest(vector: number[], excludeIds?: Set<string>): Motif | null {
    if (!vector || vector.length === 0) return null;
    let best: Motif | null = null;
    let bestScore = -Infinity;
    for (const m of this.motifs) {
      if (excludeIds && excludeIds.has(m.id)) continue;
      const emb = m.embedding as number[];
      if (!emb || emb.length === 0) continue;
      const s = cosineSimilarity(vector, emb);
      if (s > bestScore) {
        bestScore = s;
        best = m;
      }
    }
    return best;
  }
}


