import { Motif } from '../types/motif';

export interface BonusDetail {
  type: 'tarot' | 'iching' | 'title' | 'chapter';
  multiplier: number;
  label: string; // human-readable label for UI
}

export interface ScoringResult {
  totalPoints: number;
  basePoints: number;
  bonuses: BonusDetail[];
}

export function calculateScore(
  fused: Motif,
  target: Motif,
  similarity: number
): ScoringResult {
  const basePoints = calculateBase(similarity);
  const bonuses = calculateBonuses(fused, target);
  const totalPoints = applyBonuses(basePoints, bonuses);
  return { totalPoints, basePoints, bonuses };
}

function calculateBase(similarity: number): number {
  const s = Math.max(0, Math.min(1, similarity || 0));
  const linear = 120 * s;
  const quad = 800 * (s * s);
  const cubic = 3000 * (s * s * s);
  return Math.floor(linear + quad + cubic);
}

function calculateBonuses(a: Motif, b: Motif): BonusDetail[] {
  const bonuses: BonusDetail[] = [];
  const tarot = tarotMatch(a, b);
  if (tarot) bonuses.push(tarot);
  const ich = ichingMatch(a, b);
  if (ich) bonuses.push(ich);
  const title = titleMatch(a, b);
  if (title) bonuses.push(title);
  const chapter = chapterMatch(a, b);
  if (chapter) bonuses.push(chapter);
  return bonuses;
}

function applyBonuses(basePoints: number, bonuses: BonusDetail[]): number {
  let mult = 1;
  for (const b of bonuses) mult *= b.multiplier;
  return Math.floor(basePoints * mult);
}

function tarotMatch(a: Motif, b: Motif): BonusDetail | null {
  if (
    a.tarot_index !== undefined &&
    b.tarot_index !== undefined &&
    a.tarot_index === b.tarot_index
  ) {
    return { type: 'tarot', multiplier: 1.8, label: `Same tarot (${a.tarot_index})` };
  }
  return null;
}

function ichingMatch(a: Motif, b: Motif): BonusDetail | null {
  if (
    a.iching_hexagram_number !== undefined &&
    b.iching_hexagram_number !== undefined
  ) {
    const au = Math.floor(((a.iching_hexagram_number as number) - 1) / 8);
    const al = (((a.iching_hexagram_number as number) - 1) % 8);
    const bu = Math.floor(((b.iching_hexagram_number as number) - 1) / 8);
    const bl = (((b.iching_hexagram_number as number) - 1) % 8);
    if (au === bu || al === bl) {
      return { type: 'iching', multiplier: 1.4, label: 'Shared I Ching trigram' };
    }
  }
  return null;
}

function titleMatch(a: Motif, b: Motif): BonusDetail | null {
  const aw = (a.name || '').toLowerCase().split(/\s+/).filter(w => w.length > 3);
  const bw = (b.name || '').toLowerCase().split(/\s+/).filter(w => w.length > 3);
  const ignore = new Set(['the', 'and', 'with', 'from', 'into', 'over', 'under', 'this', 'that', 'these', 'those']);
  const aset = new Set(aw.filter(w => !ignore.has(w)));
  let matches = 0;
  for (const w of bw) if (aset.has(w) && !ignore.has(w)) matches++;
  if (matches > 0) {
    const multiplier = 1.0 + (Math.min(matches, 2) * 0.25);
    return { type: 'title', multiplier, label: `${matches} shared title word(s)` };
  }
  return null;
}

function chapterMatch(a: Motif, b: Motif): BonusDetail | null {
  if (a.chapter && b.chapter && a.chapter === b.chapter) {
    return { type: 'chapter', multiplier: 1.2, label: `Same chapter (${a.chapter})` };
  }
  return null;
}


